49		dbPath, err := FindFile(filepath.Join(chatsDir, "*", agentID, "store.db"))
50		if err != nil {
51			return nil, fmt.Errorf("finding store.db for agent %s: %w", agentID, err)
52		}
53		if dbPath == "" {
54			return nil, fmt.Errorf("no store.db found for agent %q (searched %s/*/%s/store.db)", agentID, chatsDir, agentID)
55		}
56	
57		// Export database
58		storeData, err := ExportDB(ctx, dbPath)
59		if err != nil {
60			return nil, fmt.Errorf("exporting database: %w", err)
61		}
62	
63		// Find transcript
64		transcriptPath, err := FindFile(filepath.Join(projectsDir, "*", "agent-transcripts", agentID+".jsonl"))
65		if err != nil {
66			return nil, fmt.Errorf("searching for transcript: %w", err)
67		}
