// seedCursorTree materializes a fake ~/.cursor tree under home and returns it.
// Callers point HOME at this tree via t.Setenv.
func seedCursorTree(t *testing.T, home string, s seed) (dbPath, transcriptPath string) {
	t.Helper()

	dbDir := filepath.Join(home, ".cursor", "chats", testWorkspace, testAgentID)
	if err := os.MkdirAll(dbDir, 0o755); err != nil {
		t.Fatalf("mkdir chats: %v", err)
